provider "aws" {
  region = "us-west-2"
}

locals {
  example_com_zone_id = "Z099999999CHECKID.com"
}

resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_route53_hosted_zone" "example_com" {
  name = "example.com"

  tags = {
    Name = "Example DNS Zone"
  }
}

resource "aws_route53_record" "example_com_ns" {
  zone_id = aws_route53_hosted_zone.example_com.id
  name    = aws_route53_hosted_zone.example_com.name
  type    = "NS"

  aliases = [
    aws_route53_hosted_zone.example_com.name_servers[0]
    aws_route53_hosted_zone.example_com.name_servers[1]
    aws_route53_hosted_zone.example_com.name_servers[2]
  ]
}

resource "aws_route53_zone_association" "example_com_association" {
  hosted_zone_id = aws_route53_hosted_zone.example_com.id
  vpc            = aws_vpc.example_vpc.id

  vpc_region = aws_vpc.example_vpc.region
}

output "example_com_zone_id" {
  value = aws_route53_hosted_zone.example_com.id
}

output "example_com_zone_name_servers" {
  value = aws_route53_hosted_zone.example_com.name_servers
}
```

This Terraform configuration creates a VPC, a Route 53 hosted zone for the domain `example.com`, and associates the hosted zone with the VPC. It also creates NS records for the hosted zone and outputs the zone ID and name servers for easier DNS configuration. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

