  type   = "A"
  alias {
    name                   = aws_db_instance.primary.address
    zone_id                = aws_db_instance.primary.availability_zone
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "replica_1_record" {
  zone_id = aws_route53_zone.main_zone.zone_id
  name   = aws_db_instance.replica_1.address
  type   = "A"
  alias {
    name                   = aws_db_instance.replica_1.address
    zone_id                = aws_db_instance.replica_1.availability_zone
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "replica_2_record" {
  zone_id = aws_route53_zone.main_zone.zone_id
  name   = aws_db_instance.replica_2.address
  type   = "A"
  alias {
    name                   = aws_db_instance.replica_2.address
    zone_id                = aws_db_instance.replica_2.availability_zone
    evaluate_target_health = true
  }
}

resource "aws_route53_health_check" "db_health_check" {
  type = "EC2"
  resource_id = aws_db_instance.primary.id
  resource_type = "db_instance"
}

resource "aws_route53_weighted_record" "weighted_record" {
  zone_id = aws_route53_zone.main_zone.zone_id
  name   = aws_db_instance.primary.address
  type   = "A"
  weight = 5
  records = [
    aws_route53_record.primary_record.zone_id,
    aws_route53_record.replica_1_record.zone_id,
    aws_route53_record.replica_2_record.zone_id
  ]
