provider "aws" {
  region = "us-west-2"
}

variable "elasticbeanstalk_application_name" {
  default = "my-elasticbeanstalk-app"
}

variable "route53_zone_id" {
  default = "ZONE_ID"
}

resource "aws_elasticbeanstalk_environment" "blue_environment" {
  name                = "blue"
  application          = var.elasticbeanstalk_application_name
  solution_stack_name = "64bit Amazon Linux 2 v3.0.3 running Node.js 14.x"
}

resource "aws_elasticbeanstalk_environment" "green_environment" {
  name                = "green"
  application          = var.elasticbeanstalk_application_name
  solution_stack_name = "64bit Amazon Linux 2 v3.0.3 running Node.js 14.x"
}

resource "aws_route53_record" "blue_route53_record" {
  zone_id = var.route53_zone_id
  name    = "my-website"
  type    = "A"
  alias {
    name                   = aws_elasticbeanstalk_environment.blue_environment.cname
    zone_id                = aws_elasticbeanstalk_environment.blue_environment.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "green_route53_record" {
  zone_id = var.route53_zone_id
  name    = "my-website"
  type    = "A"
  alias {
    name                   = aws_elasticbeanstalk_environment.green_environment.cname
    zone_id                = aws_elasticbeanstalk_environment.green_environment.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_health_check" "elasticbeanstalk_health_check" {
  healthy_threshold   = 3
  unhealthy_threshold = 10
  timeout             = 5
  interval            = 30
  matcher             = "200,301,302"
  resource_path       = "/"
  comment             = "Health check for Elastic Beanstalk environments"
}

resource "aws_route53_weighted_routing_policy" "weighted_routing_policy" {
  name = "weighted-routing-policy"
  weighted_routing_policy_config {
    weight_100 = aws_route53_record.blue_route53_record.id
    weight {
      weight = 1
      record_id = aws_route53_record.green_route53_record.id
    }
  }
  health_check_id = aws_route53_health_check.elasticbeanstalk_health_check.id
}
