```hcl
provider "aws" {
  region = "us-west-2"
}

variable "domain_name" {
  default = "example.com"
}

variable "ipv4_address" {
  default = "1.2.3.4"
}

resource "aws_route53_domain" "route53_domain" {
  name = var.domain_name
}

resource "aws_route53_zone" "route53_hosted_zone" {
  name = aws_route53_domain.route53_domain.name
}

resource "aws_route53_record" "route53_hosted_zone_record" {
  zone_id = aws_route53_zone.route53_hosted_zone.zone_id
  name    = aws_route53_zone.route53_hosted_zone.name
  type    = "A"
  ttl     = "300"
  records = [var.ipv4_address]
}
```

This configuration uses the `aws` provider with the `us-west-2` region. It defines a variable for the domain name and the IPv4 address, and creates a Route 53 domain, a hosted zone for the domain, and a hosted zone record to map the domain name to the IPv4 address. The domain name and IPv4 address are specified as variables with default values. The `aws_route53_domain`, `aws_route53_zone`, and `aws_route53_record` resources are created in the order specified by the dependency graph inferred from the prompt.

