          "kinesis:GetRecords",
          "kinesis:PutRecord",
          "kinesis:PutRecordBatch"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_firehose_iam_role_policy_attachment" {
  role       = aws_iam_role.kinesis_firehose_iam_role.name
  policy_arn = aws_iam_policy.kinesis_firehose_iam_policy.arn
}

resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_stream" {
  name        = "kinesis_firehose_stream"
  destination = {
    opensearch = {
      index_name = "firehose-index"
      role_arn   = aws_iam_role.kinesis_firehose_iam_role.arn
    }
  }
  vpc_configuration {
    subnet_configuration {
      subnet_id = aws_subnet.kinesis_firehose_subnet_1.id
    }
    subnet_configuration {
      subnet_id = aws_subnet.kinesis_firehose_subnet_2.id
    }
  }
  tags = {
    Name = "kinesis_firehose_stream"
  }
  security_configuration {
    firehose_encryption_configuration {
      encryption_type = "KMS"
      kms_key_arn     = aws_kms_key.example_key.arn
    }
  }
  kms_key_arn = aws_kms_key.example_key.arn
  tags = {
    Name = "kinesis_firehose_stream"
  }
}
```

This Terraform HCL code creates a Kinesis Firehose Delivery Stream with an OpenSearch Destination within a VPC. It also creates the necessary IAM Role and Policy for the Kinesis Firehose service. The VPC, subnets, and security group are also created as required. The example KMS key `aws_kms_key.example_key` is not part of the prompt, but it is included here as a placeholder for a real KMS key that should be used in a production environment.

