  geolocation_rule {
    locations = ["US"]
    priority = 10
    route_id = aws_route53_route.primary_us_route.id
  }

  geolocation_rule {
    locations = ["EU"]
    priority = 20
    route_id = aws_route53_route.primary_eu_route.id
  }
}

resource "aws_route53_route_table_association" "primary_zone_association" {
  route_table_id = aws_route53_route_table.primary_route_table.id
  hosted_zone_id = aws_route53_zone.primary.id
}

resource "aws_route53_gateway_endpoint" "us_endpoint" {
  name = "us-endpoint"
  type = "VPC"
  vpc_id = aws_vpc.example.id
  private_dns_name = "us-endpoint.${aws_route53_zone.primary.name}"
}

resource "aws_route53_gateway_endpoint" "eu_endpoint" {
  name = "eu-endpoint"
  type = "VPC"
  vpc_id = aws_vpc.example.id
  private_dns_name = "eu-endpoint.${aws_route53_zone.primary.name}"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}
```

This Terraform HCL program creates a Route 53 zone called "primary.example.com" and associates it with a route table that utilizes a user's location to route them to the nearest endpoint of the primary route 53 zone. The program uses Route 53 resources such as route tables, routes, health checks, geolocation configurations, and route table associations. It also creates two VPC gateway endpoints for US and EU regions. The provider configuration is set to the US West (Oregon) region.

