resource "aws_s3_bucket_lifecycle" "wellcomecollection_platform_infra_lifecycle" {
  bucket = aws_s3_bucket.wellcomecollection_platform_infra.id

  rule {
    id     = "delete-tmp-objects"
    prefix = "tmp/"

    expiration {
      days = 30
    }
  }

  rule {
    id     = "transition-to-ia"
    prefix = ""

    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }
  }

  rule {
    id     = "delete-noncurrent-versions"
    noncurrent_version_transition {
      days          = 90
      storage_class = "STANDARD"
    }
  }
}
