variable "key_pair_name" {
  default = "my-key-pair"
}

variable "security_group_id" {
  default = "my-security-group"
}

resource "aws_ami_from_instance" "latest_amazon_linux_2_ami" {
  name                   = "latest_amazon_linux_2_ami_${md5(data.aws_ami.amazon_linux_2.id)}"
  source_instance_id     = aws_instance.ami_instance.id
  launch_configuration_name = aws_ami_launch_configuration.ami_launch_config.name
}

resource "aws_ami_launch_configuration" "ami_launch_config" {
  name                   = "ami_launch_config"
  image_id               = aws_ami_from_instance.latest_amazon_linux_2_ami.id
  instance_type          = "t2.medium"
  key_name               = var.key_pair_name
  security_groups        = [var.security_group_id]
  user_data              = <<-EOF
                            #!/bin/bash
                            yum update -y
                            yum install -y aws-cfn-bootstrap
                            cfn-init -v --stack ${aws_stack_info.this_stack.id} --resource aws_ami_launch_configuration.ami_launch_config
                            EOF
  instance_initiated_shutdown_behavior = "terminate"
  block_device_mappings = [
    {
      device_name = "/dev/xvda"
      ebs = {
        volume_size = 8
        volume_type = "gp2"
      }
    }
  ]

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_instance" "ami_instance" {
  ami           = aws_ami_from_instance.latest_amazon_linux_2_ami.id
  instance_type = "t2.medium"
  key_name      = var.key_pair_name
  security_groups = [var.security_group_id]

  lifecycle {
    create_before_destroy = true
  }
}
```

This configuration creates an AWS AMI from the latest Amazon Linux 2 AMI, sets the CPU count to 2 and cores per thread per core to 2 by using a launch configuration and an instance to check the AMI properties. Make sure to replace `my-key-pair` and `my-security-group` with your own key pair name and security group ID.

