  memcached_subnet_group_name = "${local.memcached_cluster_name}-subnet-group"
}

resource "aws_security_group" "memcached_cluster_sg" {
  name        = local.memcached_cluster_sg_name
  description = "Security group for Memcached Cluster"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 11211
    to_port     = 11211
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For simplicity, replace with your VPC CIDR block or a whitelist of IPs
  }
}

resource "aws_subnet_group" "memcached_subnet_group" {
  name       = local.memcached_subnet_group_name
  description = "Subnet group for Memcached Cluster"
  vpc_id     = data.aws_vpc.default.id

  tags = {
    Name = local.memcached_cluster_name
  }
}

resource "aws_iam_role" "memcached_cluster_role" {
  name = "${local.memcached_cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "memcached.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "memcached_cluster_policy" {
  name = "${local.memcached_cluster_name}-policy"

  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "memcached:GetCluster",
          "memcached:GetClusterConfig",
          "memcached:GetClusterMetrics",
          "memcached:GetClusterStatus",
          "memcached:GetClusterVersions",
          "memcached:Put",
          "memcached:Get",
          "memcached:Delete",
          "memcached:Flush",
          "memcached:AddNodes",
          "memcached:RemoveNodes",
          "memcached:ReplaceNodes",
          "memcached:RebootNodes",
          "memcached:AuthorizeCacheNode",
          "memcached:RevokeCacheNodeAuthorizations",
          "memcached:DescribeCacheNodes",
          "memcached:DescribeCacheClusters",
          "memcached:CreateCacheCluster",
          "memcached:DeleteCacheCluster",
          "memcached:ModifyCacheCluster",
          "memcached:DescribeCacheClusterEvents",
          "memcached:CreateCacheClusterEventSubscription",
          "memcached:DeleteCacheClusterEventSubscription"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "memcached_cluster_policy_attachment" {
  name = "${local.memcached_cluster_name}-policy-attachment"
  roles = [aws_iam_role.memcached_cluster_role.name]
  policy_arn = aws_iam_policy.memcached_cluster_policy.arn
}

resource "aws_memcached_cluster" "memcached_cluster" {
  name = local.memcached_cluster_name
  engine_version = "1.5.14"
  node_config {
    instance_type = "cache.m5.large"
    node_port = 11211
    node_count = 3
  }
  security_group_ids = [aws_security_group.memcached_cluster_sg.id]
  subnet_group_name = aws_subnet_group.memcached_subnet_group.name
  vpc_security_group_ids = [aws_security_group.memcached_cluster_sg.id]
}

resource "aws_memcached_cluster_event_subscription" "memcached_cluster_event_subscription" {
  name = "${local.memcached_cluster_name}-event-subscription"
  sns_topic_arn = aws_sns_topic.memcached_cluster_notifications.arn
  cluster_arn = aws_memcached_cluster.memcached_cluster.arn
}
```

This Terraform configuration creates an AWS Memcached Cluster with an IAM Role and Policy for access, and an Event Subscription for notifications. The configuration assumes the existence of an SNS topic for notifications, a VPC, and subnets within the VPC. It also creates a security group and a subnet group for the Memcached Cluster.

