  master_username    = "my-username"
  master_password    = "my-strong-password"
  database_name      = "my-database"
  cluster_type       = "single-node"
  number_of_nodes    = 2
  vpc_security_group_ids = [aws_security_group.redshift_sg.id]
  subnet_group_name = aws_redshift_subnet_group.redshift_subnet_group.name

  logging {
    bucket_name = "my-redshift-logs"
    log_destination_type = "S3"
  }

  snapshot_copy {
    destination_region = "us-west-1"
    retention_period = 7
  }

  timeouts {
    create = "1h"
    update = "1h"
    delete = "1h"
  }
}

resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name        = "redshift-subnet-group"
  subnet_ids  = [aws_subnet.redshift_subnet.id]
  tags = {
    Name = "redshift-subnet-group"
  }
}

resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.redshift_vpc.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "redshift_cluster_role" {
  name = "redshift_cluster_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "redshift_cluster_policy" {
  name = "redshift_cluster_policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "redshift:StartCluster"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "redshift:StopCluster"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_cluster_role_policy_attachment" {
  role       = aws_iam_role.redshift_cluster_role.name
  policy_arn = aws_iam_policy.redshift_cluster_policy.arn
}

resource "aws_iam_instance_profile" "redshift_cluster_instance_profile" {
  name = "redshift_cluster_instance_profile"
  role = aws_iam_role.redshift_cluster_role.name
}

resource "aws_redshift_cluster_parameter_group" "redshift_cluster_parameter_group" {
