aws_iam_role: resource
  required attributes: assume_role_policy
  optional attributes: description, force_detach_policies, id, managed_policy_arns, max_session_duration, name, name_prefix, path, permissions_boundary, tags, tags_all
  computed-only attributes: arn, create_date, unique_id
  nested blocks:
