provider "aws" {
  region = var.region
}

variable "regions" {
  description = "List of regions where DynamoDB tables will be created"
  type        = list(string)
  default     = ["us-east-1", "us-west-1", "us-west-2"]
}

variable "region" {
  description = "Region to use for local execution"
  type        = string
  default     = "us-east-1"
}

locals {
  table_names = [for r in var.regions : "${replace(r, "-", "_")}_dynamodb_table"]
}

resource "aws_dynamodb_table" "dynamodb_table" {
  for_each = { for i, r in var.regions : i => r => local.table_names[i] }

  name           = each.value
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  lifecycle {
    ignore_changes = [
      arn,
      stream_arn,
      stream_label
    ]
  }
}
```

This Terraform HCL program creates DynamoDB tables in the specified regions (us-east-1, us-west-1, and us-west-2). It uses the `for_each` meta-argument to iterate over the regions and create a DynamoDB table for each one. The `local` block is used to generate a list of table names based on the regions. The `lifecycle` block is used to ignore changes to computed-only attributes, ensuring that the tables are only recreated if their configuration changes.

