provider "aws" {
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

data "github_repository" "terraform_provider_aws" {
  owner    = "hashicorp"
  repository = "terraform-provider-aws"
}

resource "aws_s3_bucket" "terraform_state" {
  bucket = "terraform-state-${data.aws_caller_identity.current.account_id}-${random_id.bucket_id.hex}"
  acl    = "private"
}

resource "random_id" "bucket_id" {
  byte_length = 4
}

resource "aws_iam_role" "sagemaker_notebook_role" {
  name = "sagemaker_notebook_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "sagemaker_notebook_policy" {
  name = "sagemaker_notebook_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.terraform_state.arn}/*"
        Sid      = "AllowSagemakerNotebookAccessToTerraformState"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_notebook_policy_attachment" {
  role       = aws_iam_role.sagemaker_notebook_role.name
  policy_arn = aws_iam_policy.sagemaker_notebook_policy.arn
}

resource "aws_sagemaker_notebook_instance" "sagemaker_notebook_instance" {
  name_prefix = "tf-sagemaker-notebook"
  instance_type = "ml.t2.medium"
  role_arn = aws_iam_role.sagemaker_notebook_role.arn
  image_id = data.aws_ami.sagemaker_notebook_image.id
  notebook_instance_lifecycle {
    create_timeout = "d10m"
    delete_timeout = "d10m"
    terminate_timeout = "d10m"
  }
  s3_input_path = "${aws_s3_bucket.terraform_state.id}/notebooks"
  s3_output_path = "${aws_s3_bucket.terraform_state.id}/notebooks"
  tags = {
    Name = "Terraform SageMaker Notebook"
  }
}

data "aws_ami" "sagemaker_notebook_image" {
  most_recent = true
  filter {
    name   = "name"
    values = ["Amazon Linux 2 AMI for SageMaker *"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
  owners = ["amazon"]
}
```

This configuration creates an AWS SageMaker notebook instance using the Terraform AWS provider downloaded from GitHub. It also creates an IAM role for the SageMaker notebook instance, an IAM policy to allow access to the Terraform state S3 bucket, and an S3 bucket for storing Terraform state files. The IAM role and policy are attached to the SageMaker notebook instance. The S3 bucket name is generated using a random ID to ensure uniqueness.

