    gateway_id = aws_internet_gateway.main_igw.id
  }
}

resource "aws_subnet_route_table_association" "us_east_1a_subnet_association" {
  subnet_id      = aws_subnet.us_east_1a_subnet.id
  route_table_id = aws_route_table.main_route_table.id
}

resource "aws_subnet_route_table_association" "us_east_1b_subnet_association" {
  subnet_id      = aws_subnet.us_east_1b_subnet.id
  route_table_id = aws_route_table.main_route_table.id
}

resource "aws_security_group" "allow_ssh_sg" {
  name        = "allow_ssh"
  description = "Allow SSH inbound traffic"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_launch_configuration" "amazon_linux_launch_config" {
  name          = "amazon_linux_launch_config"
  image_id      = data.aws_ami.amazon_linux_2.id
  instance_type = "t2.micro"
  security_groups = [aws_security_group.allow_ssh_sg.id]

  block_device {
    device_name = "/dev/xvda"
    volume_size = 50
    volume_type = "gp2"
  }
}

resource "aws_autoscaling_group" "amazon_linux_asg" {
  name                 = "amazon_linux_asg"
  launch_configuration = aws_launch_configuration.amazon_linux_launch_config.name
  vpc_zone_identifier  = [aws_subnet.us_east_1a_subnet.id, aws_subnet.us_east_1b_subnet.id]

  min_size = 2
  max_size = 2
}
```

This Terraform configuration creates a VPC, two subnets in us-east-1a and us-east-1b, an internet gateway, a route table, and associates the subnets with the route table. It also creates a security group that allows SSH access, a launch configuration for Amazon Linux 2 instances with a 50GB EBS volume, and an Auto Scaling group with the launch configuration. The instances will be of the t2.micro instance type.

