provider "aws" {
  region = "us-west-2"
}

locals {
  example_table_name = "ExampleTableName"
  example_table_log_group_name = "/aws/dynamodb/${local.example_table_name}/contributor-insights"
}

resource "aws_cloudwatch_log_group" "example_table_log_group" {
  name              = local.example_table_log_group_name
  retention_in_days = 14
}

resource "aws_dynamodb_table" "example_table_name" {
  name           = local.example_table_name
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }
}

resource "aws_cloudwatch_log_stream" "example_table_log_stream" {
  name           = aws_cloudwatch_log_group.example_table_log_group.name
  log_group_name = aws_cloudwatch_log_group.example_table_log_group.name
}

resource "aws_iam_role" "example_table_insights_role" {
  name = "example_table_insights_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "example_table_insights_policy" {
  name        = "example_table_insights_policy"
  description = "IAM policy for AWS Contributor Insights on ExampleTableName"

  path        = "/"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
          "logs:FilterLogEvents",
          "logs:GetLogGroupFields",
          "logs:GetLogRecord",
          "logs:GetQueryResults",
          "logs:StartQuery",
          "logs:StopQuery"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "example_table_insights_attachment" {
  name       = "example_table_insights_attachment"
  roles      = [aws_iam_role.example_table_insights_role.name]
  policy_arn = aws_iam_policy.example_table_insights_policy.arn
}

resource "aws_dynamodb_table_contributor_insights" "example_table_contributor_insights" {
  table_name = aws_dynamodb_table.example_table_name.name
  role_arn   = aws_iam_role.example_table_insights_role.arn
