  }

  client_authentication {
    iam = true
  }

  configuration_info {
    arn = aws_msk_cluster_configuration.msk_configuration.arn
    revision = aws_msk_cluster_configuration.msk_configuration.latest_revision
  }

  open_monitoring {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.msk_log_group.arn
  }

  timeouts {
