 Here is the Terraform HCL program that meets the requirements:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  subnet_cidr = "10.0.1.0/24"
}

data "aws_vpc" "default" {
  default = true
}

data "aws_availability_zones" "available" {
}

resource "aws_subnet" "msk_subnet" {
  count = length(data.aws_availability_zones.available.names)

  cidr_block = local.subnet_cidr
  vpc_id     = data.aws_vpc.default.id
  availability_zone_id = data.aws_availability_zones.available.names[count.index]
}

resource "aws_iam_role" "msk_cluster_iam_role" {
  name = "msk_cluster_iam_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_cluster_iam_role_policy_attachment" {
  role       = aws_iam_role.msk_cluster_iam_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonManagedStreamingForKafkaPolicy"
}

resource "aws_iam_instance_profile" "msk_cluster_instance_profile" {
  name = "msk_cluster_instance_profile"
  role = aws_iam_role.msk_cluster_iam_role.name
}

resource "aws_launch_configuration" "msk_cluster_launch_configuration" {
  name_prefix = "msk_cluster_launch_config"
  image_id     = "ami-0c94855ba95c574c8" # Amazon Linux 2 AMI (HVM), SSD Volume Type - amd64
  instance_type = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.msk_cluster_instance_profile.name

  user_data = base64encode(<<-EOT
    #!/bin/bash
    yum install -y epel-release
    yum install -y jmx_exporter node_exporter
    systemctl enable jmx_exporter
    systemctl enable node_exporter
    systemctl start jmx_exporter
    systemctl start node_exporter
    EOT
  )

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_autoscaling_group" "msk_cluster_autoscaling_group" {
  name = "msk_cluster_autoscaling_group"
  launch_configuration = aws_launch_configuration.msk_cluster_launch_configuration.name
  min_size             = 1
  max_size             = 1
  vpc_zone_identifier   = [aws_subnet.msk_subnet[0].id]
}

resource "aws_msk_cluster" "msk_cluster" {
  name                     = "my_msk_cluster"
  kafka_version            = "2.8.0"
  number_of_broker_nodes   = 1
  bootstrap_brokers        = ["${aws_autoscaling_group.msk_cluster_autoscaling_group.id}"]
  client_subnets           = [aws_subnet.msk_subnet[0].cidr_block]
  instance_type            = "t3.micro"
  security_groups          = [aws_autoscaling_group.msk_cluster_autoscaling_group.vpc_security_group_id]
  encryption_in_transit_enabled = true

  logging_info {
    log_group = aws_cloudwatch_log_group.msk_cluster_log_group.name
  }

  open_monitoring {
    cloudwatch_logs {
      log_group = aws_cloudwatch_log_group.msk_cluster_log_group.name
      log_stream = aws_cloudwatch_log_stream.msk_cluster_log_stream.name
    }
  }

  tags = {
    Name = "my_msk_cluster"
  }
}

resource "aws_cloudwatch_log_group" "msk_cluster_log_group" {
  name = "/aws/msk/my_msk_cluster"
}

resource "aws_cloudwatch_log_stream" "msk_cluster_log_stream" {
  name = "msk_cluster_log_stream"
  log_group_name = aws_cloudwatch_log_group.msk_cluster_log_group.name
}
```

This Terraform configuration creates a managed MSK cluster with jmx_exporter and node_exporter both enabled. It uses the AWS provider version ~> 5.75 and Terraform version ~> 1.9.8. The configuration includes IAM roles, an instance profile, a launch configuration, an autoscaling group, and a log group for the MSK cluster. The configuration also sets up the MSK cluster with the specified Kafka version, number of broker nodes, and security groups. The user data for the instances is configured to install jmx_exporter and node_exporter and start them at boot.

