    log_producer_request_timestamp_type = "CreateTime"
    log_retention_hours = 168
    log_retention_minutes = 1440
    log_request_timestamp_type = "CreateTime"
    log_request_timeout_ms = 30000
    log_replica_fetch_timeout_ms = 30000
    log_replica_request_timeout_ms = 30000
    log_replica_request_timeout_percent = 95
    log_request_compression_type = "snappy"
    log_request_correlation_id = true
    log_request_timestamp_type = "CreateTime"
    log_replica_request_correlation_id = true
    log_replica_request_timestamp_type = "CreateTime"
    log_replica_request_timeout_ms = 30000
    log_replica_request_timeout_percent = 95
    log_request_compression_type = "snappy"
  }

  timeouts {
    create = "30m"
    update = "30m"
    delete = "30m"
  }
}

resource "aws_iam_role" "us-east1_msk_role" {
  name = "us-east1_msk_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "us-east1_msk_policy_attachment" {
  role       = aws_iam_role.us-east1_msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonManagedStreamingForKafkaFullAccess"
}
```

This Terraform HCL program creates a serverless MSK cluster in the us-east1 region with an associated IAM role. It also creates a VPC and a subnet for the MSK cluster to use. The VPC and subnet are created with a CIDR block of 10.0.0.0/16 and 10.0.0.0/24 respectively, which are realistic offline-valid values. The MSK cluster uses the standard configuration with 168 hours of log retention and snappy compression. The IAM role allows the MSK cluster to access the necessary AWS managed policies for MSK.

