provider "aws" {
  region = "us-east-1"
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnet_ids" "subnets" {
  vpc_id = data.aws_vpc.default.id
}

data "aws_iam_policy_document" "msk_cluster_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["msk.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_iam_for_cluster" {
  name = "msk_iam_for_cluster_us_east1"
  assume_role_policy = data.aws_iam_policy_document.msk_cluster_assume_role_policy.json
}

resource "aws_iam_role_policy_attachment" "msk_iam_for_cluster_policy_attachment" {
  role       = aws_iam_role.msk_iam_for_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKReadOnlyAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name                     = "msk_cluster_us_east1"
  inter_broker_communication_encryption_enabled = true
  kafka_version                    = "2.8.0"
  number_of_broker_nodes           = 3
  open_monitoring_dashboard        = true
  open_mbe_dashboard               = true
  open_mbe_metrics                 = true
  open_mbe_logs                    = true
  open_mbe_tracing                 = true
  open_mbe_web_console             = true
  vpc_id                           = data.aws_vpc.default.id

  kafka_network_properties = {
    broker_security_config_properties = {
      inter_broker_listener_name = "PLAINTEXT://"
      listener_security_config_properties = {
        security_protocol = "PLAINTEXT"
      }
    }
  }

  client_authentication {
    iam
  }

  broker_node_group_info {
    client_subnets = element(data.aws_subnet_ids.subnets.ids, [0])
    instance_type  = "t3.micro"
    security_groups = [aws_security_group.msk_cluster_sg.id]
  }

  broker_node_group_info {
    client_subnets = element(data.aws_subnet_ids.subnets.ids, [1])
    instance_type  = "t3.micro"
    security_groups = [aws_security_group.msk_cluster_sg.id]
  }

  broker_node_group_info {
    client_subnets = element(data.aws_subnet_ids.subnets.ids, [2])
    instance_type  = "t3.micro"
    security_groups = [aws_security_group.msk_cluster_sg.id]
  }

  configuration_info {
    arn = aws_msk_configuration.msk_configuration.arn
    revision = aws_msk_configuration.msk_configuration.latest_revision_number
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_kms_key.arn
  }

  logging_info {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.msk_log_group.arn
  }

  open_monitoring {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.msk_log_group.arn
  }

  timeouts {
    create = "30m"
    update = "30m"
    delete = "30m"
  }
}

resource "aws_security_group" "msk_cluster_sg" {
  name_prefix = "msk_cluster_sg_"
  vpc_id      = data.aws_vpc.default.id
}

resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = "/aws/msk/msk_cluster_us_east1"
}

resource "aws_kms_key" "msk_kms_key" {
  description = "KMS key for MSK cluster encryption at rest"
  policy      = data.aws_iam_policy_document.msk_kms_key_policy.json
}

data "aws_iam_policy_document" "msk_kms_key_policy" {
  statement {
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.msk_iam_for_cluster.arn]
    }
  }
}
```

This Terraform configuration creates a serverless MSK cluster with 3 broker nodes in the us-east1 region. It also creates an IAM role and attaches the AmazonMSKReadOnlyAccess policy to it. The configuration assumes the existence of a default VPC and creates a security group, log group, and KMS key for the MSK cluster. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

