}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "msk_key" {
  description             = "KMS key for MSK encryption"
  enable_key_rotation     = true
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name                      = local.msk_cluster_name
  open_monitoring                   = true
  encryption_in_transit_enabled     = true
  encryption_at_rest_kms_key_arn    = aws_kms_key.msk_key.arn
  number_of_broker_nodes            = 3
  zookeeper_connect_string          = aws_msk_zookeeper_connect_string.this.connect_string
  bootstrap_topic_configuration {
    topic_arn = aws_msk_topic.bootstrap_topic.arn
  }
}

resource "aws_msk_zookeeper_connect_string" "this" {
  cluster_id = aws_msk_cluster.msk_cluster.id
}

resource "aws_msk_topic" "bootstrap_topic" {
  cluster_id = aws_msk_cluster.msk_cluster.id
  topic_name = "bootstrap-topic"
}

resource "aws_cloudwatch_log_group" "msk_log_group" {
  name              = "/aws/msk/${local.msk_cluster_name}"
  retention_in_days = 14
}

resource "aws_s3_bucket" "msk_s3_bucket" {
  bucket = local.msk_s3_bucket_name
  acl    = "private"
}

resource "aws_s3_bucket_policy" "msk_s3_bucket_policy" {
  bucket = aws_s3_bucket.msk_s3_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.msk_s3_bucket.arn}/*"
        Sid       = "AllowMSKToWriteToS3"
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_stream" {
  name        = local.msk_firehose_stream_name
  destination = "extended_s3"
  s3_configuration {
    bucket_arn = aws_s3_bucket.msk_s3_bucket.arn
  }
}
```

This Terraform HCL program creates an MSK cluster with 3 broker nodes, outputs to a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream. The MSK cluster is encrypted at rest and has open monitoring enabled. The S3 bucket is private, and the Kinesis Firehose delivery stream is configured to write data to the specified S3 bucket.

