```hcl
provider "aws" {
  region = "us-west-2"
  version = "~> 5.75"
}

variable "mysql_cluster_allocated_storage" {
  default = "100"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_security_group" "example" {
  name        = "terraform_example_sg"
  description = "Security group for MySQL cluster"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "mysql_cluster" {
  engine                 = "aurora-mysql"
  master_username        = "admin"
  master_password        = "password"
  skip_final_snapshot    = true
  vpc_security_group_ids  = [aws_security_group.example.id]
  availability_zones     = ["us-west-2a", "us-west-2b", "us-west-2c"]
  database_name          = "mydb"
  master_port            = 3306
  backup_retention_period = 7
  preferred_backup_window = "07:00-09:00"
  storage_encrypted      = true
  storage_type            = "gp2"
  allocated_storage      = var.mysql_cluster_allocated_storage

  setting {
    name  = "backup_storage_encrypted"
    value = "true"
  }
}

resource "aws_rds_cluster_instance" "mysql_cluster_instance" {
  count = length(aws_rds_cluster.mysql_cluster.cluster_members.*.id)

  engine                 = aws_rds_cluster.mysql_cluster.engine
  allocated_storage      = var.mysql_cluster_allocated_storage
  instance_class         = "db.r5.large"
  apply_immediately      = true
  skip_final_snapshot    = true
  vpc_security_group_ids  = [aws_security_group.example.id]
  cluster_identifier     = aws_rds_cluster.mysql_cluster.id

  setting {
    name  = "backup_storage_encrypted"
    value = "true"
  }
}
```

