  description = "MySQL master password"
  default     = "my_master_password"
}

resource "aws_rds_cluster_parameter_group" "my_us_east_1_mysql_cluster_parameter_group" {
  name        = "my-us-east-1-mysql-cluster-parameter-group"
  family      = "mysql8.0"
  description = "Parameter group for MySQL cluster in us-east-1"

  parameter {
    name  = "max_connections"
    value = "1000"
  }

  parameter {
    name  = "allocated_storage"
    value = "100"
  }
}

resource "aws_rds_cluster" "my_us_east_1_mysql_cluster" {
  cluster_identifier = "my-us-east-1-mysql-cluster"

  engine = "mysql"
  engine_version = "8.0.27"

  availability_zones = local.azs

  master_username = var.my_username
  master_password = var.my_password

  backup_window = "03:00-06:00"
  maintenance_window = "mon:00:00-mon:03:00"

  parameter_group_name = aws_rds_cluster_parameter_group.my_us_east_1_mysql_cluster_parameter_group.name

  skip_final_snapshot = true
}

resource "aws_rds_cluster_instance" "my_us_east_1a_mysql_instance" {
  count = length(local.azs)

  cluster_identifier = aws_rds_cluster.my_us_east_1_mysql_cluster.cluster_identifier
  engine             = aws_rds_cluster.my_us_east_1_mysql_cluster.engine
  engine_version     = aws_rds_cluster.my_us_east_1_mysql_cluster.engine_version

  instance_class = "db.t3.micro"

  availability_zone = elements(local.azs, count.index)[0]
}
```

This configuration creates an RDS MySQL cluster with 3 instances in us-east-1a, us-east-1b, and us-east-1c. It also sets the maximum connections and allocated storage for the cluster. The MySQL master username and password are set to the provided variables with default values.

