provider "aws" {
  region = "us-west-2"
}

variable "custom_cidr_block" {
  description = "The CIDR block for the custom route"
  default     = "10.0.0.0/16"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main_vpc.id
}

resource "aws_route_table" "custom_route_table" {
  vpc_id = aws_vpc.main_vpc.id

  route {
    cidr_block     = aws_vpc.main_vpc.cidr_block
    gateway_id     = aws_internet_gateway.main_igw.id
    carrier_gateway_id = ""
    destination_prefix_list_id = ""
    egress_only_gateway_id = ""
    instance_id = ""
    instance_owner_id = ""
    local_gateway_id = ""
    nat_gateway_id = ""
    network_interface_id = ""
    transit_gateway_id = ""
    vpc_endpoint_id = ""
    vpc_peering_connection_id = ""
  }

  route {
    cidr_block = var.custom_cidr_block
    gateway_id = aws_internet_gateway.main_igw.id
  }
}

aws_vpc.main_vpc.default_route_table_id = aws_route_table.custom_route_table.id
