    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:PutObject",
          "s3:GetObject",
          "s3:DeleteObject",
          "s3:ListAllObjectsV2"
        ]
        Effect   = "Allow"
        Resource  = "${aws_s3_bucket.inventory_bucket.arn}/*"
      },
      {
        Action = [
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource  = "${aws_s3_bucket.inventory_reports_bucket.arn}"
      }
    ]
  })
}

