  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "cs_class_codepipeline_policy_attachment" {
  name       = "${local.codepipeline_role_name}_policy_attachment"
  roles      = [local.codepipeline_role_name]
  policy_arn = aws_iam_policy.cs_class_codepipeline_policy.arn
}

resource "aws_codebuild_project" "cs_class_autograder" {
  name          = "cs_class_autograder"
  description   = "Autograder for a CS class"
  service_role  = aws_iam_role.cs_class_codepipeline_role.arn

  artifacts = {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image       = "aws/codebuild/standard:4.0"
    type        = "LINUX_CONTAINER"
  }

  source {
    type      = "GITHUB"
    location  = "https://github.com/your_org/your_repo.git"
    buildspec = file("buildspec.yml")
  }

  lifecycle {
    ignore_changes = [
      source
    ]
  }
}

resource "aws_codepipeline" "cs_class_codepipeline" {
  name     = "cs_class_codepipeline"
  role_arn = aws_iam_role.cs_class_codepipeline_role.arn

  artifact_store {
    location = aws_s3_bucket.cs_class_results_bucket.id
    type     = "S3"
  }

  stage {
    name = "Source"

    action {
      name             = "SourceAction"
      category         = "Source"
      owner            = "AWS"
      provider         = "GitHub"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration {
        Owner      = "your_org"
        Repo       = "your_repo"
        OAuthToken = var.github_oauth_token
      }
    }
  }

  stage {
    name = "Build"

    action {
      name             = "BuildAction"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]
      version          = "1"

      configuration {
        ProjectName = aws_codebuild_project.cs_class_autograder.name
      }
    }
  }

  post {
    action {
      name             = "StoreResults"
      category         = "Store"
      owner            = "AWS"
      provider         = "S3"
      input_artifacts  = ["build_output"]
      output_artifacts = []
      version          = "1"

      configuration {
        BucketName = aws_s3_bucket.cs_class_results_bucket.bucket
        KeyPrefix  = "results/${aws_codepipeline.cs_class_codepipeline.id}/"
      }
    }
  }
}

variable "github_oauth_token" {
  description = "GitHub OAuth token for accessing the repository"
  type        = string
  default     = "your_github_oauth_token"
}
```

This Terraform HCL program creates an AWS CodePipeline that triggers a CodeBuild project with students' code from GitHub, stores the results in an S3 bucket, and defines a custom IAM role and policy to provide the necessary permissions for the CodePipeline. The GitHub OAuth token is provided as a variable with a default value.

