  name              = local.backup_selection_name
  selection_type    = "EC2_INSTANCE"
  vault_id          = aws_backup_vault.backup_vault.id
  aws_resource_id   = aws_ec2_instance.backup_ec2_instance.id
  aws_resource_type = "aws_ec2_instance"

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_backup_schedule" "backup_schedule" {
  name      = local.backup_schedule_name
  schedule_expression = "cron(0 0 * * ? *)"
  plan_id = aws_backup_plan.backup_plan.id
}

resource "aws_backup_policy" "backup_policy" {
  name          = local.backup_policy_name
  vault_id      = aws_backup_vault.backup_vault.id
