  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_backup_job" "backup_job" {
  name          = "backup-job"
  plan_id       = aws_backup_plan.backup_plan.id
  selection_id  = aws_backup_selection.backup_selection.id
  policy_id     = aws_backup_policy.backup_policy.id

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "backup_attach" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSBackupPowerUser"
}
