  vpc_cidr            = "10.0.0.0/16"
}

resource "aws_vpc" "main" {
  cidr_block = local.vpc_cidr
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = local.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.main.id
  cidr_block = local.public_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ec2_sg" {
  name        = "terraform_ec2_sg"
  description = "Security group for EC2 instances"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "ec2_backup_role" {
  name = "terraform_ec2_backup_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "ec2_backup_policy" {
  name        = "terraform_ec2_backup_policy"
  description = "Policy for EC2 Backup"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "backup:CreateBackup",
          "backup:GetBackup",
          "backup:ListBackups",
          "backup:StartBackup",
          "backup:StopBackup"
        ]
        Effect   = "Allow"
        Resource  = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_backup_attach" {
  role       = aws_iam_role.ec2_backup_role.name
  policy_arn = aws_iam_policy.ec2_backup_policy.arn
}

resource "aws_key_pair" "ssh_key" {
  key_name   = "terraform_ssh_key"
  public_key = file("~/.ssh/id_rsa.pub")
}

resource "aws_instance" "ec2_instance" {
  ami           = "ami-0c94855ba95c574c8" # Amazon Linux 2 AMI (HVM), SSD Volume Type - amd64
  instance_type = "t3.micro"

  vpc_subnet_id  = aws_subnet.private.id
  key_name       = aws_key_pair.ssh_key.key_name
  iam_instance_profile = aws_iam_role.ec2_backup_role.name
  security_groups = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "terraform_ec2_instance"
  }
}

resource "aws_backup_vault" "backup_vault" {
  name = "terraform_backup_vault"
}

resource "aws_backup_plan" "backup_plan" {
  name              = "terraform_backup_plan"
  rule              = [0]
  schedule_expression = "cron(0 0 * * ? *)" # Daily backup at midnight

  rule {
    backup_selection = aws_backup_selection.backup_selection.id
  }
}

resource "aws_backup_selection" "backup_selection" {
  name        = "terraform_backup_selection"
  plan_id     = aws_backup_plan.backup_plan.id
  iam_role_arn = aws_iam_role.ec2_backup_role.arn

  resource_type = "EC2_INSTANCE"
  resources     = [aws_instance.ec2_instance.id]
}
```

This Terraform configuration creates an EC2 instance and sets up a backup plan to back it up every day at midnight using AWS Backup. It also creates the necessary VPC, subnets, internet gateway, route table, security group, IAM role, and IAM policy. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

