    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_execution_policy" {
  name = local.lambda_execution_policy_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "lambda_execution_role_policy_attachment" {
  name = "lambda_execution_role_policy_attachment"
  roles = [aws_iam_role.lambda_execution_role.name]
  policy_arn = aws_iam_policy.lambda_execution_policy.arn
}

resource "aws_lambda_function" "daily_utc_executor" {
  function_name = "daily_utc_executor"
  runtime = "python3.8"
  role = aws_iam_role.lambda_execution_role.arn
  handler = "index.main"
  source_code_hash = filebase64sha256("path/to/your/lambda_function_zip")

  environment {
    variables = {
      TIME_ZONE = "UTC"
    }
  }
}

resource "aws_eventbridge_rule" "daily_utc_rule" {
  name = local.event_bridge_rule_name
  description = "Trigger Lambda function daily at 7 UTC"
  schedule_expression = "rate(1 day)"

  event_pattern = jsonencode({
    source = ["aws.lambda"]
    detail-type = ["AWS API Call via CloudTrail"]
    detail = {
      eventSource = ["aws.lambda.amazonaws.com"]
      eventName = ["CreateFunction"]
    }
  })
}

resource "aws_eventbridge_target" "daily_utc_target" {
  name = local.event_bridge_target_name
  rule = aws_eventbridge_rule.daily_utc_rule.name
  arn = aws_lambda_function.daily_utc_executor.arn
}
```

This Terraform HCL configuration creates the necessary AWS resources to run a Lambda function daily at 7 UTC. It includes an IAM role, IAM policy, Lambda function, EventBridge rule, and EventBridge target. The Lambda function code should be provided separately and uploaded using the Terraform AWS Lambda provider.

