provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the S3 bucket's origin access identity"
  default     = "your_vpc_id"
}

resource "aws_route53_zone" "video_streaming_site_zone" {
  name = "video-streaming-site.com"
}

resource "aws_s3_bucket" "video_streaming_bucket" {
  bucket = "video-streaming-bucket-${aws_route53_zone.video_streaming_site_zone.name}"
}

resource "aws_s3_bucket_policy" "video_streaming_bucket_policy" {
  bucket = aws_s3_bucket.video_streaming_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = "s3:GetObject"
        Resource = "${aws_s3_bucket.video_streaming_bucket.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceVpc" = var.vpc_id
          }
        }
      }
    ]
  })
}

resource "aws_cloudfront_origin_access_control_config" "video_streaming_origin_access_control" {
  name = "video-streaming-origin-access-control"
  origin_access_control_origin_config {
    s3_origin_config {
      origin_access_identity = aws_s3_bucket.video_streaming_bucket.bucket_regional_domain_name
    }
  }
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  origin = {
    domain_name = aws_s3_bucket.video_streaming_bucket.bucket_regional_domain_name
    origin_id   = "S3-Origin"

    s3_origin_config {
