  description = "RDS encryption key"
  alias       = var.rds_kms_key_alias
}

resource "aws_rds_cluster" "postgres_cluster" {
  cluster_identifier      = "postgres-cluster"
  engine                  = "postgres"
  engine_version          = var.rds_engine_version
  availability_zones      = ["us-west-2a", "us-west-2b"]
  database_name           = "postgres-db"
  master_username         = "postgres-user"
  master_password         = "strong_password"
  skip_final_snapshot     = true
  vpc_security_group_ids   = [aws_security_group.rds_security_group.id]
  backup_retention_period = 7
  db_subnet_group_name    = aws_db_subnet_group.rds_subnet_group.name
  kms_key_id              = aws_kms_key.rds_encryption_key.arn
  storage_encrypted       = true

  scaling_configuration {
    auto_pause               = true
    max_capacity             = 2
    min_capacity             = 1
    seconds_before_timeout  = 60
    timeout_action           = "terminate"
  }
}

resource "aws_rds_cluster_instance" "primary_rds_instance" {
  cluster_identifier      = aws_rds_cluster.postgres_cluster.id
  engine                  = aws_rds_cluster.postgres_cluster.engine
  instance_class          = "db.t3.micro"
  allocation_extras       = "dedicated-cpu-credits"
  availability_zone       = aws_rds_cluster.postgres_cluster.availability_zones[0]
}

resource "aws_rds_cluster_instance" "secondary_rds_instance" {
  cluster_identifier      = aws_rds_cluster.postgres_cluster.id
  engine                  = aws_rds_cluster.postgres_cluster.engine
  instance_class          = "db.t3.micro"
  allocation_extras       = "dedicated-cpu-credits"
  availability_zone       = aws_rds_cluster.postgres_cluster.availability_zones[1]
}

resource "aws_rds_cluster_parameter_group" "postgres_parameter_group" {
  name   = "postgres-parameter-group"
  family = "postgres13"

  parameter {
    name  = "max_connections"
    value = "100"
  }
}

resource "aws_security_group" "rds_security_group" {
  name_prefix = "rds-security-group"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
