}

resource "aws_rds_proxy_security_group" "aurora_mysql_proxy_security_group" {
  name_prefix = "rds_proxy_security_group"
  vpc_id      = aws_vpc.main_vpc.id
}

resource "aws_rds_proxy_authorization" "aurora_mysql_proxy_authorization" {
