provider "aws" {
  region = "us-west-2"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  owners = ["amazon"]
}

resource "aws_lightsail_blueprint" "basic_lightsail_blueprint" {
  name              = "basic_lightsail_blueprint"
  platform          = "LINUX_64BIT"
  image_id          = data.aws_ami.amazon_linux_2.id
  bundle_id         = "amazon_lightsail_basic_blueprint"
  root_block_device {
    block_device_type = "gp2"
    device_name       = "root"
    volume_size       = 20
  }
}

resource "aws_lightsail_instance" "basic_lightsail_instance" {
  name              = "basic_lightsail_instance"
  blueprint_id      = aws_lightsail_blueprint.basic_lightsail_blueprint.id
  region            = "us-west-2"
}

resource "aws_lightsail_instance_action" "set_user_data" {
  instance_name = aws_lightsail_instance.basic_lightsail_instance.name
  action_type   = "USER_DATA"
  user_data     = filebase64("user_data.sh")
}
```

