 To create an S3 Glacier vault for long-term data archiving, the following Terraform HCL program is provided. This configuration includes an IAM role for the Glacier vault, which allows the vault to perform necessary operations.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  glacier_vault_name = "longterm-data-archiving-vault"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "glacier_vault_role" {
  name = "${local.glacier_vault_name}-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "glacier_vault_policy" {
  name = "${local.glacier_vault_name}-iam-policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:InitiateJob",
          "glacier:ListVaults",
          "glacier:GetJob",
          "glacier:DeleteVault",
          "glacier:GetVaultNotificationsConfiguration",
          "glacier:PutVaultNotificationsConfiguration",
          "glacier:GetVaultInventory",
          "glacier:GetVaultLock",
          "glacier:PutVaultLock",
          "glacier:GetVaultAccessPolicy",
          "glacier:PutVaultAccessPolicy"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glacier_vault_policy_attachment" {
  role       = aws_iam_role.glacier_vault_role.name
  policy_arn = aws_iam_policy.glacier_vault_policy.arn
}

