provider "aws" {
  region = "us-west-2"
}

locals {
  long_term_data_bucket_name = "long-term-data-bucket-${random_id.suffix.hex}"
  backup_bucket_name          = "backup-long-term-data-bucket-${random_id.suffix.hex}"
}

resource "random_id" "suffix" {
  byte_length = 2
}

resource "aws_s3_bucket" "long_term_data_bucket" {
  bucket = local.long_term_data_bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_s3_bucket" "backup_bucket" {
  bucket = local.backup_bucket_name
  acl    = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  replication {
    role = aws_iam_role.backup_role.arn

    rules = [
      {
        prefix = "${local.long_term_data_bucket_name}/"
        status = "Enabled"

        destination {
          bucket = aws_s3_bucket.long_term_data_bucket.id
          storage_class = "INTELLIGENT_TIERING"
        }
      }
    ]
  }
}

resource "aws_iam_role" "backup_role" {
  name = "backup_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}
```

This Terraform configuration creates two S3 buckets: one for long-term data storage and another for backup. The backup bucket replicates data from the long-term data bucket using an IAM role for the S3 service. The IAM role is assumed by the S3 service to allow it to replicate the data. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75. The S3 bucket names are generated using a random ID to ensure uniqueness.

