        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_glacier_vault.glacier_vault.arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "glacier_vault_encryption" {
  bucket = aws_s3_bucket.glacier_vault.id

  rule {
    apply_server_side_encryption_by_aws_kms_key_id = aws_kms_key.glacier_vault_key.arn
    bucket_key_enabled = true
  }
}

resource "aws_kms_key" "glacier_vault_key" {
  description = "KMS key for S3 Glacier vault"
}

resource "aws_s3_bucket_versioning" "glacier_vault_versioning" {
  bucket = aws_s3_bucket.glacier_vault.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "glacier_vault_public_access" {
  bucket = aws_s3_bucket.glacier_vault.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "glacier_vault_encryption_at_rest" {
  bucket = aws_s3_bucket.glacier_vault.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle" "glacier_vault_lifecycle" {
  bucket = aws_s3_bucket.glacier_vault.id

  rule {
    id = "move-to-glacier"

    transition {
      days          = 30
      storage_class = "GLACIER"
    }
  }
}

resource "aws_s3_bucket_policy" "glacier_vault_access_policy" {
  bucket = aws_s3_bucket.glacier_vault.id

  policy = jsonencode({
    Version = "2012-10-17"
