provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "ID of the VPC where the resources will be created"
  type        = string
  default     = "vpc-0123456789abcdef0"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the VPC"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]
}

variable "security_group_name" {
  description = "Name of the security group for the load balancer"
  type        = string
  default     = "internal-load-balancer-sg"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_security_group" "example" {
  name        = var.security_group_name
  description = "Security group for the internal load balancer"
  vpc_id      = var.vpc_id
}

resource "aws_subnet" "example" {
  count             = length(var.subnet_ids)
  cidr_block        = element(split("/", var.subnet_ids[count.index]), 1)
  vpc_id            = aws_vpc.example.id
  availability_zone = element(split("a", var.subnet_ids[count.index]), 1)
}

resource "aws_lb" "internal_load_balancer" {
  name               = "internal-load-balancer"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.example.id]
  subnets            = [for subnet in aws_subnet.example : subnet.id]
}

resource "aws_lb_subnet_mapping" "internal_subnet_mapping" {
  count             = length(aws_subnet.example)
  load_balancer_arn = aws_lb.internal_load_balancer.arn
  subnet_id         = aws_subnet.example[count.index].id
}

resource "aws_lb_target_group" "internal_target_group" {
  name     = "internal-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id
}

resource "aws_lb_target_group_attachment" "internal_target_group_attachment" {
  count          = length(aws_subnet.example)
  target_group_arn = aws_lb_target_group.internal_target_group.arn
  target_id      = aws_instance.example[count.index].id
  port           = 80
}

resource "aws_instance" "example" {
  count         = length(aws_subnet.example)
  ami           = "ami-0123456789abcdef0" # replace with a valid AMI ID for the region
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.example[count.index].id
  vpc_security_group_ids = [aws_security_group.example.id]
}
```

This configuration creates an internal load balancer with private IP addresses in the specified VPC and subnets. It also creates EC2 instances in the specified subnets and registers them as targets for the load balancer. Replace the `ami` variable with a valid AMI ID for the region.

