}

resource "aws_instance" "application_instance" {
  count = 1

  ami           = local.ami
  instance_type = "t2.micro"

  vpc_subnet_id  = aws_subnet.main.id
  key_name       = local.my_key_pair

  tags = {
    Name = "application-instance"
  }
}

resource "aws_alb_target_group_attachment" "application_target_group_attachment" {
  count = 1

  target_group_arn = aws_alb_target_group.application_target_group.arn
  target_id        = aws_instance.application_instance[count.index].id
  port             = 80
}
```

This Terraform configuration creates an Application Load Balancer, a target group, a listener, an EC2 instance, and attaches the instance to the target group. The configuration includes a VPC, subnet, and security group for the resources to reside in. The health check for the target group is also defined. The AMI and key pair used for the EC2 instance are placeholders and should be replaced with appropriate values for your environment.

