 ```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  vpc_id = aws_vpc.default.id
}

# Create a basic RDS instance
resource "aws_db_instance" "rds_instance" {
  allocated_storage      = 20
  storage_type           = "gp2"
  engine                 = "aurora-postgresql"
  engine_version         = "13.7"
  instance_class         = "db.t2.micro"
  db_name                = "mydb"
  username               = "myuser"
  password               = "mypassword"
  parameter_group_name   = "default.aurora-postgresql13"
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
  publicly_accessible    = false
}

# Create a security group for the RDS instance
resource "aws_security_group" "rds_security_group" {
  name_prefix = "rds-sg"
  vpc_id      = local.vpc_id
}

# Create an IAM role for RDS access
resource "aws_iam_role" "rds_access_role" {
  name = "rds_access_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM instance profile for RDS access
resource "aws_iam_instance_profile" "rds_access_profile" {
  name = "rds_access_profile"
  role = aws_iam_role.rds_access_role.name
}

# Attach RDS access policy to the IAM role
resource "aws_iam_policy_attachment" "rds_access_policy_attachment" {
  name       = "rds-access-policy-attachment"
  roles      = [aws_iam_role.rds_access_role.name]
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}
