provider "aws" {
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

locals {
  rds_backup_bucket_name = "rds-backups-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket" "rds_backup_bucket" {
  bucket = local.rds_backup_bucket_name
  acl    = "private"
}

resource "aws_s3_bucket_object" "s3_backup" {
  bucket = aws_s3_bucket.rds_backup_bucket.id
  key    = "rds_backup.db"
  source = "path/to/rds_backup.db"
}

resource "aws_iam_role" "rds_to_s3" {
  name = "rds_to_s3_access"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_access" {
  name = "rds_to_s3_access_policy"

  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.rds_backup_bucket.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceVpc" = "${aws_vpc.main.id}"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_to_s3_s3_access" {
  role       = aws_iam_role.rds_to_s3.name
  policy_arn = aws_iam_policy.s3_access.arn
}

