  instance_class         = "db.t2.micro"
  db_name                = "mydb"
  username               = "myuser"
  password               = "mypassword"
  parameter_group_name   = "default.postgres13"
  backup_retention_period = 7
  skip_final_snapshot    = true
  vpc_security_group_ids = [aws_security_group.rds_access.id]

  restore_from_db_snapshot = aws_rds_db_snapshot.latest.id

  depends_on = [aws_s3_bucket_object.s3_backup]
}

resource "aws_rds_db_snapshot" "latest" {
  db_instance_identifier = aws_rds_db_instance.restored_rds_instance.id
  final_snapshot_identifier = "latest"
}

resource "aws_security_group" "rds_access" {
