resource "aws_db_subnet_group" "db_subnet_group" {
  name       = local.db_subnet_group_name
  subnet_ids = [aws_vpc.main.ids[0], aws_vpc.main.ids[1]]
}

resource "aws_kms_key" "specific_kms_key" {
  description = "Specific KMS key for managing RDS master passwords"
}

resource "aws_db_instance_parameter_group" "managed_db_parameter_group" {
  name   = "managed-db-parameter-group"
  family = "mysql8.0"
}

resource "aws_db_instance" "managed_db_instance" {
  engine                 = "mysql"
  engine_version         = "8.0"
  instance_class         = "db.t2.micro"
  allocated_storage      = 20
  storage_type           = "gp2"
  parameter_group_name   = aws_db_instance_parameter_group.managed_db_parameter_group.name
  username               = "admin"
  password               = "CHANGE_ME_IN_TF_FILE"
  skip_final_snapshot    = true
  db_subnet_group_name   = local.db_subnet_group_name
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  kms_key_id             = aws_kms_key.specific_kms_key.arn
}

resource "aws_security_group" "rds_sg" {
  name_prefix = "rds-sg"
  vpc_id      = data.aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Temporarily allow all traffic for demonstration purposes.
  }
}

resource "aws_secretsmanager_secret" "db_master_password_secret" {
  name        = local.db_master_password_secret_name
  description = "Secret for the database master password"
}

resource "aws_secretsmanager_secret_version" "db_master_password_version" {
  secret_id     = aws_secretsmanager_secret.db_master_password_secret.id
  secret_string = aws_db_instance.managed_db_instance.password
}

resource "aws_secretsmanager_secret_rotation_schedule" "db_master_password_rotation" {
  name        = local.db_master_password_rotation_schedule_name
  secret_id   = aws_secretsmanager_secret.db_master_password_secret.id
  rotation_lambda_arn = "arn:aws:lambda:us-west-2:123456789012:function:rotate_rds_password"
}

resource "aws_db_instance" "managed_db_instance_with_kms" {
  engine                 = "mysql"
  engine_version         = "8.0"
  instance_class         = "db.t2.micro"
  allocated_storage      = 20
  storage_type           = "gp2"
  parameter_group_name   = aws_db_instance_parameter_group.managed_db_parameter_group.name
  username               = "admin"
  password               = aws_secretsmanager_secret.db_master_password_secret.arn
  skip_final_snapshot    = true
  db_subnet_group_name   = local.db_subnet_group_name
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  kms_key_id             = aws_kms_key.specific_kms_key.arn
  identifier             = "managed-db-instance-with-kms"
  depends_on             = [aws_db_instance.managed_db_instance]
}
```

This Terraform HCL configuration creates an AWS RDS MySQL instance with Managed Master Passwords via Secrets Manager, using a specific KMS key. It also sets up a rotation schedule for the master password secret and a parameter group for the RDS instance. The configuration includes a VPC, subnet group, and security group for the RDS instance, and it uses the specified region. The password for the RDS instance is stored in AWS Secrets Manager, and the RDS instance is configured to use the specified KMS key for managing master passwords.

